PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate
WHERE {
  VALUES ?person { dbr:Katey_Sagal dbr:Adam_DeVine dbr:Brittany_Snow dbr:John_Michael_Higgins dbr:Skylar_Astin dbr:Anna_Kendrick dbr:Elizabeth_Banks dbr:Alexis_Knapp dbr:Chrissie_Fit dbr:Ester_Dean dbr:Hailee_Steinfeld dbr:Anna_Camp dbr:Rebel_Wilson dbr:Hana_Mae_Lee }
  ?person dbo:birthDate ?birthDate .
  FILTER (?birthDate = "1986-03-09"^^xsd:date)
}
LIMIT 100

